'use client'

/**
 * AgreementGate - 首次登录强制协议确认（奕霖 2026-07-06 13:37 决定）
 *
 * 触发条件：complianceStore.agreedAt === null 或版本号变化
 * 通过条件：勾选 3 个 checkbox 后才能点"同意并继续"
 * 一次性：localStorage 记 agreedAt + agreedVersion，后续不再骚扰
 *
 * 渲染全屏遮罩（fixed inset:0 z-index 9999），未确认时不显示 children。
 * 这是 ToC 产品合规底线，漏了出事用户可以告你没尽到告知义务。
 */

import { toast } from '@/lib/ui-bus'
import { useState, useEffect } from 'react'
import { createPortal } from 'react-dom'
import { useComplianceStore, shouldShowAgreement } from '@/stores/complianceStore'
import { useUserStore } from '@/stores/userStore'
import { BUSINESS_CONFIG } from '@/config/business.config'

export default function AgreementGate({ children }: { children: React.ReactNode }) {
  const { agreedAt, agreedVersion, agree } = useComplianceStore()
  const user = useUserStore((s) => s.user)
  const [mounted, setMounted] = useState(false)
  const [scrollToBottom, setScrollToBottom] = useState(false)
  const [checked1, setChecked1] = useState(false)  // 用户协议
  const [checked2, setChecked2] = useState(false)  // 隐私政策
  const [checked3, setChecked3] = useState(false)  // AI 风险说明
  const [showAgreementFull, setShowAgreementFull] = useState(false)
  const [showPrivacyFull, setShowPrivacyFull] = useState(false)

  useEffect(() => { setMounted(true) }, [])

  // ⭐ MEMORY §269 — 2026-08-28 奕霖紧急跳过:?skip-agree=1 query param → 自动 agree
  // 背景:清缓存/服务重启后用户 localStorage 的 agreedAt 失效 → AgreementGate 弹出 →
  //       蒙层挡死所有点击(用户试关键词时 chip 在底层但 modal 顶层拦截,Playwright 实测证实)
  // 方案:URL 加 ?skip-agree=1 一键跳过(持久化到 localStorage,下次正常访问不再弹)
  useEffect(() => {
    if (typeof window === 'undefined') return
    try {
      const params = new URLSearchParams(window.location.search)
      if (params.get('skip-agree') === '1') {
        agree()
        const cleanUrl = window.location.pathname + window.location.hash
        window.history.replaceState({}, '', cleanUrl)
      }
    } catch (e) {}
  }, [])

  // SSR 阶段不要渲染遮罩，避免 hydration 闪烁
  if (!mounted) return <>{children}</>

  const needAgree = shouldShowAgreement(agreedAt, agreedVersion)

  const isLoggedIn = !!user?.id
  // ⭐ 奕霖 2026-07-15 13:41 修复：已登录用户跳过协议确认
  // 原因：协议确认遮挡 TabBar 导致用户找不到底部按键
  // 已登录用户 = 已验证手机号 = 已隐含同意协议 = 信任状态
  if (!needAgree || isLoggedIn) return <>{children}</>

  const allChecked = checked1 && checked2 && checked3

  function handleAgree() {
    if (!allChecked) return
    agree()
  }

  return (
    <>
      {children}
      {/* ⭐ 奕霖 2026-07-06 14:07：Portal 渲染到 body + z-index 99999，避免被 BottomTabBar 遮挡 */}
      {typeof document !== 'undefined' && createPortal(
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby="agreement-title"
        style={{
          position: 'fixed',
          inset: 0,
          zIndex: 99999,
          background: 'rgba(44, 24, 16, 0.96)',
          backdropFilter: 'blur(20px)',
          WebkitBackdropFilter: 'blur(20px)',
          display: 'flex',
          flexDirection: 'column',
          overflow: 'hidden',
        }}
      >
        {/* 顶部标题 */}
        <div
          style={{
            padding: 'calc(20px + env(safe-area-inset-top, 0px)) 24px 16px',
            textAlign: 'center',
            borderBottom: '1px solid rgba(184, 134, 11, 0.12)',
            flexShrink: 0,
          }}
        >
          <div style={{ fontSize: 36, marginBottom: 8 }}>💈</div>
          <h1
            id="agreement-title"
            style={{
              fontSize: 22, fontFamily: "Rye, 'Noto Serif SC', Georgia, serif", letterSpacing: 4, textShadow: '0 1px 0 rgba(0,0,0,0.5), 0 2px 0 rgba(0,0,0,0.4), 0 3px 6px rgba(0,0,0,0.3)',
              fontWeight: 700,
              color: '#b8860b',
              margin: 0,
              letterSpacing: 1,
            }}
          >
            欢迎使用造型师
          </h1>
          <p style={{
            fontSize: 13,
            color: 'rgba(255, 255, 255, 0.55)',
            margin: '6px 0 0',
          }}>
            使用前请阅读并同意以下条款
          </p>
        </div>

        {/* 可滚动协议区 */}
        <div
          style={{
            flex: 1,
            overflowY: 'auto',
            padding: '20px 24px',
            minHeight: 0,
          }}
        >
          {/* 三个 checkbox 块 */}
          <CheckItem
            checked={checked1}
            onChange={setChecked1}
            label="我已阅读并同意"
            link="《用户服务协议》"
            onLinkClick={() => setShowAgreementFull(true)}
            color="#b8860b"
          />
          <CheckItem
            checked={checked2}
            onChange={setChecked2}
            label="我已阅读并同意"
            link="《隐私政策》"
            onLinkClick={() => setShowPrivacyFull(true)}
            color="#b8860b"
          />
          <CheckItem
            checked={checked3}
            onChange={setChecked3}
            label="我已知晓 AI 发型顾问（造型助手）的"
            link="功能局限与风险"
            onLinkClick={() => {
              setChecked3(true)
              toast.info('造型助手 AI 发型顾问说明：\n\n1. 造型助手是发型顾问，不是造型师、不是医生\n2. 造型建议基于常见营养知识，可能因个人体质不同有偏差\n3. 食物过敏（坚果/海鲜等）/慢病人群/孕期请咨询专业造型师或医生\n4. 配送时效受天气/路况影响，以实际送达为准\n5. 不替代专业医疗建议，如有不适请及时就医\n\n我已了解并接受以上，方可使用造型助手功能。')
            }}
            color="#b8860b"
          />

          {/* 风险提示框 */}
          <div
            style={{
              marginTop: 20,
              padding: '14px 16px',
              background: 'rgba(251, 191, 36, 0.08)',
              border: '1px solid rgba(251, 191, 36, 0.25)',
              borderRadius: 12,
              fontSize: 12,
              color: 'rgba(255, 255, 255, 0.75)',
              lineHeight: 1.65,
            }}
          >
            <div style={{ fontWeight: 700, color: '#b8860b', marginBottom: 6 }}>
              ⚠️ 重要提示
            </div>
            本服务由 {BUSINESS_CONFIG.name} 提供，<strong>本平台不收取任何款项</strong>，
            所有购物支付在门店完成（现金/微信/支付宝/银行卡）。
            平台不接触、不留存您的支付凭证。
            <br /><br />
            <strong>造型助手建议仅供参考</strong>，不替代专业造型师或医生建议。
            如有食物过敏 / 严重不适请咨询专业人士。
          </div>

          {/* 协议详情入口 */}
          <div style={{
            marginTop: 20,
            fontSize: 12,
            color: 'rgba(255, 255, 255, 0.5)',
            textAlign: 'center',
          }}>
            点击链接可查看完整协议内容
          </div>
        </div>

        {/* 底部固定按钮 */}
        <div
          style={{
            padding: '16px 24px calc(16px + env(safe-area-inset-bottom, 0px))',
            borderTop: '1px solid rgba(184, 134, 11, 0.12)',
            background: 'rgba(44, 24, 16, 0.7)',
            flexShrink: 0,
          }}
        >
          <button
            onClick={handleAgree}
            disabled={!allChecked}
            style={{
              width: '100%',
              padding: '14px 20px',
              fontSize: 15, fontFamily: "'Alfa Slab One', 'Noto Serif SC', Georgia, serif", letterSpacing: 2,
              fontWeight: 700,
              color: allChecked ? '#2c1810' : 'rgba(255, 255, 255, 0.5)',
              background: allChecked
                ? 'linear-gradient(135deg, #b8860b 0%, #8b6508 100%)'
                : 'rgba(184, 134, 11, 0.3)',
              border: 'none',
              borderRadius: 12,
              cursor: allChecked ? 'pointer' : 'not-allowed',
              boxShadow: allChecked ? '0 4px 16px rgba(184, 134, 11, 0.3)' : 'none',
              transition: 'all 0.2s ease',
              letterSpacing: 1,
            }}
          >
            {allChecked ? '✓ 同意并继续' : '请先勾选全部条款'}
          </button>
        </div>
      </div>,
        document.body,
      )}

      {/* 协议全文弹窗（简化版，避免和文档源重复） */}
      {showAgreementFull && (
        <DocumentModal
          title={`${BUSINESS_CONFIG.name}·用户服务协议`}
          version="v2.0"
          content={AGREEMENT_SUMMARY}
          onClose={() => setShowAgreementFull(false)}
        />
      )}
      {showPrivacyFull && (
        <DocumentModal
          title={`${BUSINESS_CONFIG.name}·隐私政策`}
          version="v2.0"
          content={PRIVACY_SUMMARY}
          onClose={() => setShowPrivacyFull(false)}
        />
      )}
    </>
  )
}

function CheckItem({
  checked,
  onChange,
  label,
  link,
  onLinkClick,
  color,
}: {
  checked: boolean
  onChange: (v: boolean) => void
  label: string
  link: string
  onLinkClick: () => void
  color: string
}) {
  return (
    <label
      style={{
        display: 'flex',
        alignItems: 'flex-start',
        gap: 12,
        padding: '14px 16px',
        marginBottom: 10,
        background: checked ? 'rgba(184, 134, 11, 0.06)' : 'rgba(255, 255, 255, 0.03)',
        border: checked ? '1px solid rgba(184, 134, 11, 0.3)' : '1px solid rgba(255, 255, 255, 0.08)',
        borderRadius: 12,
        cursor: 'pointer',
        transition: 'all 0.15s ease',
      }}
    >
      <div
        style={{
          width: 22,
          height: 22,
          borderRadius: 6,
          background: checked ? color : 'transparent',
          border: checked ? 'none' : '2px solid rgba(255, 255, 255, 0.25)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          flexShrink: 0,
          marginTop: 1,
          fontSize: 14,
          color: '#2c1810',
          fontWeight: 900,
        }}
      >
        {checked && '✓'}
      </div>
      <input
        type="checkbox"
        checked={checked}
        onChange={(e) => onChange(e.target.checked)}
        style={{ display: 'none' }}
      />
      <div style={{ flex: 1, fontSize: 14, color: 'rgba(255, 255, 255, 0.85)', lineHeight: 1.55 }}>
        {label}
        <button
          type="button"
          onClick={(e) => { e.preventDefault(); onLinkClick() }}
          style={{
            color,
            textDecoration: 'underline',
            background: 'transparent',
            border: 'none',
            cursor: 'pointer',
            padding: 0,
            font: 'inherit',
            fontWeight: 600,
          }}
        >
          {link}
        </button>
      </div>
    </label>
  )
}

function DocumentModal({
  title,
  version,
  content,
  onClose,
}: {
  title: string
  version: string
  content: string
  onClose: () => void
}) {
  return (
    <div
      onClick={onClose}
      style={{
        position: 'fixed',
        inset: 0,
        zIndex: 10000,
        background: 'rgba(0, 0, 0, 0.85)',
        backdropFilter: 'blur(8px)',
        WebkitBackdropFilter: 'blur(8px)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: 20,
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          width: '100%',
          maxWidth: 480,
          maxHeight: '85vh',
          background: 'linear-gradient(180deg, #2c1810 0%, #1a0e08 100%)',
          border: '1px solid rgba(184, 134, 11, 0.25)',
          borderRadius: 16,
          display: 'flex',
          flexDirection: 'column',
          overflow: 'hidden',
        }}
      >
        <div style={{
          padding: '16px 20px',
          borderBottom: '1px solid rgba(184, 134, 11, 0.12)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}>
          <div>
            <div style={{ fontSize: 16, fontWeight: 700, color: '#b8860b' }}>{title}</div>
            <div style={{ fontSize: 11, color: 'rgba(255, 255, 255, 0.5)', marginTop: 2 }}>版本 {version}</div>
          </div>
          <button
            onClick={onClose}
            style={{
              background: 'rgba(184, 134, 11, 0.3)',
              border: '1px solid rgba(184, 134, 11, 0.2)',
              color: '#b8860b',
              borderRadius: 8,
              padding: '4px 12px',
              fontSize: 13,
              cursor: 'pointer',
            }}
          >
            关闭
          </button>
        </div>
        <div style={{
          padding: '16px 20px',
          overflowY: 'auto',
          fontSize: 13,
          lineHeight: 1.7,
          color: 'rgba(255, 255, 255, 0.75)',
          flex: 1,
          whiteSpace: 'pre-wrap',
        }}>
          {content}
        </div>
      </div>
    </div>
  )
}

